	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);
 vec2 st = fragCoord / iResolution.xy;
    st *= 6.0;
 float distortion = cell_noise(fragCoord.xy, cell_size);

vec4 O=fragColor;
vec2 C=fragCoord;
  O=vec4(0);
    vec3 p,r2=iResolution,
    d=normalize(vec3((C-.5*r2.xy)/r2.y,1));  
    float i=0.,g=0.,e,s;
    for(;++i<99.;){
        p=d*g;
       p.z-=iTime*0.1;
p.xy*=ma;
        p=asin(sin(p*4.));
        float sdf=sdHexagon(p.xy,2.);
        p.xy=vec2(sdf);
