        for(int i=0;i++<6;){
			p=vec3(1.2,6.8,5.2)-abs(p);            			
          	p=p.x<p.y?p.zxy:p.zyx;
            s*=e=17.8/min(dot(p,p),11.8);
            p=abs(p)*e;
        }
        g+=e=abs(p.y)/s+.001;
        O.xyz+=(H(log(s)*.8)+.5)*exp(sin(i))/e*3e-5;
    }
    O*=O*O*O;
    vec3 color;
