    r.x = fbm(st + 1.608 * q + vec2(1.7, 9.2) + 0.15 * iTime);
    r.y = fbm(st + 1.0 * q + vec2(8.3, 2.8) + 0.126 * iTime);

    float f = fbm(st + r);

    color = mix(vec3(0.17, 0.08, 0.067),
            vec3(0.960, 0.856, 0.104),
            clamp((pow(f, 10.0)) * 4.0, 0.0, 1.0));

    color = mix(color,
            vec3(0.885, 0.436, 0.086),
            clamp(length(q), 0.0, 1.0));

    color = mix(color,
            vec3(0.959, 1.000, 0.900),
            clamp(length(r.x), 0.0, 1.0));
   vec4 fragColor2 = vec4((f*f*f+.6*f*f+.5*f)*color, 1.0);
	float v1, v2, v3;
	v1 = v2 = v3 = 0.0;

	float s2 = 0.0;
	for (int i = 0; i < 90; i++)
	{
		vec3 p = s2 * vec3(uv+distortion, iTime*0.001);

		p += vec3(.22, .3, s2 - 1.5 - sin(iTime * .13) * .1)+fragColor2.xyz+O.xyz;
		for (int i = 0; i < 8; i++)	p = abs(p) / dot(p,p) - 0.659;
		v1 += dot(p,p) * .0015 * (1.8 + sin(length(uv.xy * 13.0) + .5  - iTime * .2));
		v2 += dot(p,p) * .0013 * (1.5 + sin(length(uv.xy * 14.5) + 1.2 - iTime * .3));
		v3 += length(p.xy*10.) * .0003;
		s2 += .035;
	}

	float len = length(uv);
	v1 *= smoothstep(.7, .0, len);
	v2 *= smoothstep(.5, .0, len);
	v3 *= smoothstep(.9, .0, len);

	vec3 col = vec3( v3 * (1.5 + sin(iTime * .2) * .4),
					(v1 + v3) * .3,
					 v2) + smoothstep(0.2, .0, len) * .85 + smoothstep(.0, .6, v3) * .3;

	fragColor=vec4(min(pow(abs(col)+fragColor2.xyz, vec3(1.2)+O.xyz), 1.0), 1.0);
}
